@* A single product card showing image, name, price, rating, stock badge, and add-to-cart *@

<div class="product-card" @onclick="HandleCardClick" style="border:1px solid #ddd; border-radius:8px; padding:1rem; cursor:pointer; display:flex; flex-direction:column; gap:0.5rem;">
    <div style="background:#e0e0e0; height:160px; display:flex; align-items:center; justify-content:center; border-radius:4px; color:#888; font-size:0.85rem;">
        @Product.Name
    </div>
    <h4 style="margin:0;">@Product.Name</h4>
    <span style="font-weight:bold; color:#2a7a2a;">@Product.Price.ToString("C")</span>
    <span title="@($"{Product.Rating:F1} out of 5")">@GetStarDisplay(Product.Rating)</span>
    @if (!Product.InStock)
    {
        <span style="background:#dc3545; color:white; padding:2px 8px; border-radius:4px; font-size:0.75rem; align-self:flex-start;">Out of Stock</span>
    }
    <button disabled="@(!Product.InStock)" @onclick="HandleAddToCart" @onclick:stopPropagation="true"
            style="margin-top:auto; padding:0.5rem; border:none; border-radius:4px; background:@(Product.InStock ? "#0d6efd" : "#6c757d"); color:white; cursor:@(Product.InStock ? "pointer" : "not-allowed");">
        Add to Cart
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product);
    }

    private static string GetStarDisplay(double rating)
    {
        int filled = (int)Math.Round(rating);
        return new string('★', filled) + new string('☆', 5 - filled);
    }
}

@* Displays a grid of ProductCard components *@

<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(220px, 1fr)); gap:1rem;">
    @foreach (var product in Products)
    {
        <ProductCard Product="product"
                     OnSelected="OnProductSelected"
                     OnAddToCart="OnAddToCart" />
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = [];

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@* Filter sidebar with category checkboxes, price range, and stock toggle *@

<div style="padding:1rem; border:1px solid #ddd; border-radius:8px;">
    <h3 style="margin-top:0;">Filters</h3>

    <fieldset style="border:none; padding:0; margin-bottom:1rem;">
        <legend style="font-weight:bold; margin-bottom:0.5rem;">Categories</legend>
        @foreach (var category in Categories)
        {
            <label style="display:block; margin-bottom:0.25rem;">
                <input type="checkbox"
                       checked="@IsSelected(category)"
                       @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                @category
            </label>
        }
    </fieldset>

    <div style="margin-bottom:1rem;">
        <label style="display:block; font-weight:bold; margin-bottom:0.25rem;">Min Price</label>
        <input type="number" min="0" step="0.01" @bind="minPrice"
               style="width:100%; padding:0.35rem; box-sizing:border-box;" />
    </div>

    <div style="margin-bottom:1rem;">
        <label style="display:block; font-weight:bold; margin-bottom:0.25rem;">Max Price</label>
        <input type="number" min="0" step="0.01" @bind="maxPrice"
               style="width:100%; padding:0.35rem; box-sizing:border-box;" />
    </div>

    <label style="display:block; margin-bottom:1rem;">
        <input type="checkbox" @bind="inStockOnly" />
        <strong>In Stock Only</strong>
    </label>

    <div style="display:flex; gap:0.5rem;">
        <button @onclick="ApplyFilters"
                style="flex:1; padding:0.5rem; background:#0d6efd; color:white; border:none; border-radius:4px; cursor:pointer;">
            Apply Filters
        </button>
        <button @onclick="ClearFilters"
                style="flex:1; padding:0.5rem; background:#6c757d; color:white; border:none; border-radius:4px; cursor:pointer;">
            Clear Filters
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public ProductFilter? CurrentFilter { get; set; }

    [Parameter]
    public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private List<string> selectedCategories = [];
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    protected override void OnParametersSet()
    {
        if (CurrentFilter is not null)
        {
            selectedCategories = CurrentFilter.Categories?.ToList() ?? [];
            minPrice = CurrentFilter.MinPrice;
            maxPrice = CurrentFilter.MaxPrice;
            inStockOnly = CurrentFilter.InStockOnly;
        }
    }

    private bool IsSelected(string category) => selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked && !selectedCategories.Contains(category))
            selectedCategories.Add(category);
        else if (!isChecked)
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }
}

@* Toolbar with sort dropdown and result count label *@

<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:1rem; flex-wrap:wrap; gap:0.5rem;">
    <div>
        <label for="sort-select" style="margin-right:0.5rem; font-weight:bold;">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChanged"
                style="padding:0.35rem; border-radius:4px; border:1px solid #ccc;">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <span style="color:#555;">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <text>Showing @start–@end of @TotalCount products</text>
        }
        else
        {
            <text>No products found</text>
        }
    </span>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@* Pagination controls: Previous, numbered pages, Next *@

@if (TotalPages > 1)
{
    <nav style="display:flex; justify-content:center; align-items:center; gap:0.25rem; margin-top:1.5rem; flex-wrap:wrap;">
        <button disabled="@(CurrentPage <= 1)" @onclick="() => GoToPage(CurrentPage - 1)"
                style="padding:0.4rem 0.75rem; border:1px solid #ccc; border-radius:4px; background:white; cursor:@(CurrentPage <= 1 ? "not-allowed" : "pointer");">
            Previous
        </button>

        @foreach (var page in GetPageNumbers())
        {
            <button @onclick="() => GoToPage(page)"
                    style="padding:0.4rem 0.75rem; border:1px solid #ccc; border-radius:4px; cursor:pointer;
                           background:@(page == CurrentPage ? "#0d6efd" : "white");
                           color:@(page == CurrentPage ? "white" : "black");">
                @page
            </button>
        }

        <button disabled="@(CurrentPage >= TotalPages)" @onclick="() => GoToPage(CurrentPage + 1)"
                style="padding:0.4rem 0.75rem; border:1px solid #ccc; border-radius:4px; background:white; cursor:@(CurrentPage >= TotalPages ? "not-allowed" : "pointer");">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private int TotalPages => PageSize > 0 ? (int)Math.Ceiling((double)TotalCount / PageSize) : 1;

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != CurrentPage)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 7;
        if (TotalPages <= maxVisible)
            return Enumerable.Range(1, TotalPages);

        var start = Math.Max(1, CurrentPage - maxVisible / 2);
        var end = Math.Min(TotalPages, start + maxVisible - 1);
        if (end - start + 1 < maxVisible)
            start = Math.Max(1, end - maxVisible + 1);

        return Enumerable.Range(start, end - start + 1);
    }
}

