@page "/catalog"
@rendermode InteractiveServer
@using sv_7a4ba055761247b1ab8a31bfac2732f1.Components.Pages.Catalog
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

<div style="display:flex; gap:1.5rem; align-items:flex-start;">
    @* Left sidebar — ~25% width *@
    <aside style="flex:0 0 25%; min-width:200px;">
        <CatalogSidebar Categories="categories"
                        CurrentFilter="filter"
                        OnFilterApplied="HandleFilterApplied"
                        OnFilterCleared="HandleFilterCleared" />
    </aside>

    @* Main content area — ~75% width *@
    <main style="flex:1; min-width:0;">
        @if (errorMessage is not null)
        {
            <div style="padding:1rem; background:#f8d7da; color:#842029; border-radius:8px; margin-bottom:1rem;">
                <strong>Error:</strong> @errorMessage
                <button @onclick="LoadProducts" style="margin-left:1rem; padding:0.25rem 0.75rem; cursor:pointer;">
                    Retry
                </button>
            </div>
        }
        else if (isLoading)
        {
            <div style="text-align:center; padding:3rem; color:#888;">
                <p>Loading products…</p>
            </div>
        }
        else if (result is not null && result.Items.Count == 0)
        {
            <div style="text-align:center; padding:3rem; color:#888;">
                <p>No products match your filters.</p>
            </div>
        }
        else if (result is not null)
        {
            <CatalogToolbar SortBy="@sortBy"
                            TotalCount="result.TotalCount"
                            Page="result.Page"
                            PageSize="result.PageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="result.Items"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="currentPage"
                               TotalCount="result.TotalCount"
                               PageSize="pageSize"
                               OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    private List<string> categories = [];
    private ProductFilter filter = new(null, null, null, false);
    private PagedResult<Product>? result;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private bool isLoading;
    private string? errorMessage;

    /// <summary>Parent or layout can handle navigation to product detail.</summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await LoadProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            categories = [];
        }
    }

    private async Task LoadProducts()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            result = await ProductService.SearchAsync(filter, sortBy, currentPage, pageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
            result = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter newFilter)
    {
        filter = newFilter;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleFilterCleared()
    {
        filter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string newSortBy)
    {
        sortBy = newSortBy;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder — integrate with a cart service when available
        return Task.CompletedTask;
    }
}

